From 5a6cfb2b6442089ac42f97713f8df2964114f252 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:21:43 +0100
Subject: [PATCH] applet: collapse a connection item when it starts showing
 another connection

The list reorders by changing the data of existing delegates, so after
disconnecting an expanded VPN the connection that moved into its place
showed up expanded. Collapse the item when its connection changes.

BUG: 490504
---
 applet/ConnectionItem.qml | 9 +++++++++
 1 file changed, 9 insertions(+)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..13ae7b148 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -335,6 +335,15 @@ PlasmaExtras.ExpandableListItem {
         }
     }

+    // The list reorders by changing the data of existing delegates, so an
+    // expanded delegate can end up showing another connection
+    readonly property string uni: model.Uni
+    onUniChanged: {
+        if (expanded) {
+            collapse();
+        }
+    }
+
     onItemCollapsed: {
         connectionItem.customExpandedViewContent = detailsComponent;
         setDelayModelUpdates(false);
-- 
